// Generated by build.py; edit ../journey-music.mjs.
export const bgmTracks={
  login:{file:'login.mp3',name:'經典登入'},
  lith:{file:'lith.mp3',name:'維多利亞港'},
  ellinia:{file:'ellinia.mp3',name:'魔法森林'},
  henesys:{file:'henesys.mp3',name:'弓箭手村'},
  kerning:{file:'kerning.mp3',name:'墮落城市'},
  florina:{file:'florina.mp3',name:'海島海岸'},
  ariant:{file:'ariant.mp3',name:'沙漠旅程'}
};
export function trackForChapter(chapter){
  if(!Number.isInteger(chapter)||chapter<1||chapter>18)return null;
  return ['lith','ellinia','henesys','kerning','florina','ariant'][Math.floor((chapter-1)/3)];
}

// Two native audio decks crossfade without restarting the same regional track.
// play() is retried synchronously on a trusted user gesture if autoplay is denied.
export function createMusicPlayer({makeAudio=()=>new Audio(),now=()=>performance.now(),changed=()=>{}}={}){
  const decks=[makeAudio(),makeAudio()];
  decks.forEach(deck=>{deck.loop=true;deck.preload='metadata';deck.volume=0;});
  let active=0,wanted=null,current=null,muted=false,masterMuted=false,suspended=false,blocked=false,error=false;
  let fade=null,token=0;
  const status=()=>({wanted,current,muted,masterMuted,suspended,blocked,error,playing:Boolean(current&&!muted&&!masterMuted&&!suspended&&!blocked&&!error)});
  const notify=()=>changed(status());
  function silence(){token++;fade=null;decks.forEach(deck=>{deck.pause();deck.volume=0;});notify();}
  function attempt(){
    if(!wanted||muted||masterMuted||suspended)return;
    const next=current===wanted?active:1-active,deck=decks[next];
    if(deck.dataset?.track!==wanted){deck.src='/assets/journey/bgm/'+bgmTracks[wanted].file;deck.dataset.track=wanted;}
    const request=++token;
    let promise;
    try{promise=deck.play();}catch(reason){reject(reason);return;}
    Promise.resolve(promise).then(()=>{
      if(request!==token)return;
      const previous=active;active=next;current=wanted;blocked=false;error=false;
      fade={start:now(),from:decks.map(d=>d.volume),previous,duration:1000};notify();
    }).catch(reject);
    function reject(reason){
      if(request!==token)return;
      blocked=reason?.name==='NotAllowedError';error=!blocked;
      notify();
    }
  }
  return {
    status,
    select(key){if(key===wanted)return;wanted=key;if(!key){silence();return;}attempt();notify();},
    gesture(){if(wanted&&!muted&&!masterMuted&&!suspended&&(blocked||!current))attempt();},
    mute(value){muted=value;decks.forEach(deck=>deck.muted=muted||masterMuted);if(value)silence();else{blocked=false;error=false;attempt();}notify();},
    masterMute(value){if(masterMuted===Boolean(value))return;masterMuted=Boolean(value);decks.forEach(deck=>deck.muted=muted||masterMuted);if(masterMuted)silence();else attempt();notify();},
    suspend(value){if(value===suspended)return;suspended=value;if(value)silence();else attempt();notify();},
    tick(time){
      if(!fade)return;
      const progress=Math.max(0,Math.min(1,(time-fade.start)/fade.duration));
      decks.forEach((deck,index)=>{const target=index===active?.32:0;deck.volume=fade.from[index]+(target-fade.from[index])*progress;});
      if(progress>=1){decks[1-active].pause();fade=null;}
    },
    stop(){wanted=null;silence();current=null;notify();}
  };
}

export function initJourneyMusic({muted=false}={}){
  const control=document.getElementById('journey-music-control'),intro=document.querySelector('#intro'),section=document.getElementById('journey-game');
  if(!control||!intro||!section)return null;
  let state={phase:'ready',chapter:0,paused:false},eligible=false,raf=0;
  const menu=document.querySelector('#site-menu');
  const player=createMusicPlayer({changed:status=>{
    control.hidden=!eligible;
    control.textContent=status.masterMuted||status.muted?'BGM · 關':status.error?'BGM · 點擊重試':status.blocked?'BGM · 點擊播放':`BGM · ${bgmTracks[status.wanted]?.name||'開'}`;
    control.setAttribute('aria-pressed',String(status.playing));
    control.setAttribute('aria-label',status.masterMuted?'請先開啟喇叭，再播放背景音樂':status.playing?'關閉背景音樂':status.error?'重試背景音樂':'播放背景音樂');
    control.dataset.playing=String(status.playing);
  }});
  player.masterMute(muted);
  function sync(){
    const introBox=intro.getBoundingClientRect(),gameBox=section.getBoundingClientRect();
    eligible=-introBox.top>=introBox.height*.3&&gameBox.bottom>0;
    const key=eligible?(state.phase==='ready'?'login':trackForChapter(state.chapter+1)):null;
    player.suspend(document.hidden||Boolean(menu?.open)||state.paused);
    player.select(key);
    control.hidden=!eligible;
  }
  document.addEventListener('journeystate',event=>{state=event.detail;sync();});
  document.addEventListener('journeyreveal',event=>{
    const tools=document.querySelector('.game-tools');
    if(event.detail.ready&&tools)tools.append(control);else document.body.append(control);
  });
  window.addEventListener('scroll',sync,{passive:true});window.addEventListener('resize',sync);
  document.addEventListener('visibilitychange',sync);
  document.addEventListener('pointerdown',()=>player.gesture(),{passive:true});
  document.addEventListener('keydown',()=>player.gesture());
  control.addEventListener('click',()=>{
    const status=player.status();
    if(status.masterMuted)return;
    if(!status.playing)player.mute(false);else player.mute(true);
  });
  if(menu)new MutationObserver(sync).observe(menu,{attributes:true,attributeFilter:['open']});
  function frame(time){player.tick(time);raf=requestAnimationFrame(frame);}
  window.addEventListener('pagehide',()=>{cancelAnimationFrame(raf);player.suspend(true);});
  window.addEventListener('pageshow',event=>{if(event.persisted){sync();raf=requestAnimationFrame(frame);}});
  sync();raf=requestAnimationFrame(frame);
  return player;
}
